@reference "../../styles.css";

.hero-detail {
  @apply grid gap-6;
}

.hero-detail__back {
  @apply justify-self-start;
}

.hero-detail__header {
  @apply flex flex-wrap items-start justify-between gap-4;
}

.hero-detail__identity {
  @apply flex min-w-0 items-center gap-4;
}

.hero-detail__portrait {
  @apply size-14 shrink-0;
}

.hero-detail__names {
  @apply grid min-w-0 gap-1;
}

.hero-detail__id {
  @apply text-xs font-medium tracking-wide text-muted-foreground uppercase;
}

.hero-detail__title {
  @apply text-2xl font-bold tracking-tight text-foreground [overflow-wrap:anywhere];
}

.hero-detail__alias {
  @apply text-sm text-muted-foreground;
}

.hero-detail__badges {
  @apply flex flex-wrap items-center gap-2 pt-1;
}

.hero-detail__status {
  @apply gap-1.5;
}

.hero-detail__dot {
  @apply size-2 shrink-0 rounded-full bg-muted-foreground;
}

.hero-detail__dot--active {
  @apply bg-success;
}

.hero-detail__dot--injured {
  @apply bg-warning;
}

.hero-detail__dot--reserve {
  @apply bg-info;
}

.hero-detail__dot--mia {
  @apply bg-destructive;
}

.hero-detail__actions {
  @apply flex flex-wrap items-center gap-2;
}

.hero-detail__notice {
  @apply rounded-lg border border-border bg-muted px-4 py-2 text-sm text-foreground;
}

.hero-detail__tabs {
  @apply grid gap-4;
}

.hero-detail__tab-list {
  @apply max-w-full overflow-x-auto;
}

.hero-detail__panel-grid {
  @apply grid gap-4 lg:grid-cols-2;
}

.hero-detail__stats {
  @apply grid grid-cols-1 gap-3 sm:grid-cols-3;
}

.hero-detail__dossier {
  @apply grid gap-3;
}

.hero-detail__row {
  @apply flex flex-wrap items-center justify-between gap-2 border-b border-border pb-2 text-sm;
}

.hero-detail__term {
  @apply text-muted-foreground;
}

.hero-detail__value {
  @apply min-w-0 text-end font-medium text-foreground [overflow-wrap:anywhere];
}

.hero-detail__meters {
  @apply grid gap-5;
}

.hero-detail__abilities {
  @apply grid justify-items-start gap-3;
}

.hero-detail__note {
  @apply text-sm text-muted-foreground;
}

.hero-detail__missions-body {
  @apply grid gap-4;
}

.hero-detail__missions {
  @apply flex flex-col gap-2;
}

.hero-detail__mission {
  @apply flex flex-wrap items-center gap-3 rounded-lg border border-border px-3 py-2 text-sm;
}

.hero-detail__mission-code {
  @apply font-semibold text-muted-foreground tabular-nums;
}

.hero-detail__mission-name {
  @apply min-w-0 flex-1 font-medium text-foreground;
}

.hero-detail__form {
  @apply grid gap-6;
}

.hero-detail__fields {
  @apply grid grid-cols-1 gap-4 sm:grid-cols-2;
}

.hero-detail__form-actions {
  @apply flex flex-wrap justify-end gap-2;
}

.hero-detail__missing {
  @apply grid justify-items-start gap-3;
}

