import { serveStatic, launchChromium } from 'D:/Repos/angular-jig/harness/playwright/serve-and-visit.mjs';

const srv = await serveStatic('D:/Repos/angular-jig/dist/angular-jig/browser', { spaFallback: true });
const browser = await launchChromium();
const results = [];
const check = (label, ok) => results.push(`${ok ? 'PASS' : 'FAIL'} ${label}`);

for (const width of [375, 1280]) {
  const page = await browser.newPage({ viewport: { width, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

  await page.goto(`${srv.origin}/detail/HRO-0007`, { waitUntil: 'networkidle' });
  check(`[${width}] title renders`, (await page.locator('h1').first().textContent())?.includes('Silverwing'));
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
  check(`[${width}] no horizontal page scroll (overflow=${overflow}px)`, overflow <= 1);

  // Retire: cancel must close without removing the hero
  await page.getByRole('button', { name: 'Retire', exact: true }).click();
  check(`[${width}] retire dialog opens`, await page.getByRole('dialog').isVisible());
  await page.getByRole('dialog').getByRole('button', { name: 'Cancel', exact: true }).click();
  await page.waitForTimeout(400);
  check(`[${width}] cancel closes dialog`, (await page.getByRole('dialog').count()) === 0);
  check(`[${width}] cancel keeps hero on detail`, page.url().includes('/detail/HRO-0007'));

  // Edit: invalid name shows an error, then a valid save updates the header
  await page.getByRole('tab', { name: 'Edit', exact: true }).click();
  await page.locator('#hero-name').fill('');
  await page.locator('#hero-name').blur();
  await page.waitForTimeout(200);
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await page.waitForTimeout(200);
  check(`[${width}] empty name blocks save`, page.url().includes('/detail/HRO-0007') && (await page.locator('h1').first().textContent())?.includes('Silverwing'));
  await page.locator('#hero-name').fill('Silverwing Prime');
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await page.waitForTimeout(300);
  check(`[${width}] save updates header`, (await page.locator('h1').first().textContent())?.includes('Silverwing Prime'));

  // Retire: confirm removes the hero and returns to the roster
  await page.getByRole('button', { name: 'Retire', exact: true }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'Retire hero', exact: true }).click();
  await page.waitForURL('**/roster', { timeout: 5000 }).catch(() => {});
  check(`[${width}] confirm retire returns to roster`, page.url().endsWith('/roster'));
  const roster = await page.locator('table tbody').textContent();
  check(`[${width}] retired hero gone from roster`, !roster.includes('HRO-0007'));

  check(`[${width}] no page errors (${errors.length})`, errors.length === 0);
  if (errors.length) results.push(...errors.map((e) => `   ${e}`));
  await page.close();
}

await browser.close();
srv.close?.();
console.log(results.join('\n'));
EOF
cd D:/Repos/angular-jig && timeout 300 node "$PROBE_DIR/probe.mjs" 2>&1 | tail -60

